package android.content;
public class ClipboardManager { private static ClipData clip; private final java.util.ArrayList<OnPrimaryClipChangedListener> listeners=new java.util.ArrayList<OnPrimaryClipChangedListener>(); public interface OnPrimaryClipChangedListener { void onPrimaryClipChanged(); } public void setPrimaryClip(ClipData c) { clip=c; for(OnPrimaryClipChangedListener l:new java.util.ArrayList<OnPrimaryClipChangedListener>(listeners)) l.onPrimaryClipChanged(); } public ClipData getPrimaryClip() { return clip; } public ClipDescription getPrimaryClipDescription() { return clip==null?null:clip.getDescription(); } public boolean hasPrimaryClip() { return clip!=null && clip.getItemCount()>0; } public void clearPrimaryClip() { setPrimaryClip(null); } public void addPrimaryClipChangedListener(OnPrimaryClipChangedListener l) { listeners.add(l); } public void removePrimaryClipChangedListener(OnPrimaryClipChangedListener l) { listeners.remove(l); } public void setText(CharSequence t) { setPrimaryClip(ClipData.newPlainText(null,t)); } public CharSequence getText() { return hasPrimaryClip()?clip.getItemAt(0).getText():null; } public boolean hasText() { return getText()!=null && getText().length()>0; } }
